// ---------- Sprache wählen ----------
function detect() {
  const saved = loadLang(); if (LANGS.includes(saved)) return saved;
  return 'en';   // Standard: Englisch (Leons Vorgabe); Deutsch nur, wenn der Spieler es gewählt hat
}
let lang = detect();
const fns = [];
export const getLang = () => lang;
export function setLang(l, save = true) {
  if (!LANGS.includes(l)) return false;
  const changed = l !== lang; lang = l; if (save) saveLang(l);
  applyDoc();
  if (changed) for (const f of fns) try { f(l); } catch (e) { console.warn(e); }
  return changed;
}
export function onLang(fn) { fns.push(fn); return () => { const i = fns.indexOf(fn); if (i >= 0) fns.splice(i, 1); }; }
// <html lang> und Fenstertitel
export function applyDoc() { if (typeof document === 'undefined') return; document.documentElement.lang = lang; document.title = t('game.title'); }

// ---------- Texte ----------
export function t(key, vars) {
  const e = S[key]; if (!e) return key;
  let v = e[lang === 'en' ? 1 : 0]; if (v === undefined) v = e[0];
  if (typeof v === 'function') return v(vars || {});
  if (typeof v === 'string' && vars) return v.replace(/\{(\w+)\}/g, (m, k) => (vars[k] ?? m));
  return v;
}
export const has = key => !!S[key];
export const phrase = s => (lang === 'en' && typeof s === 'string' && PHRASE_EN[s]) || s;
export const quote = s => t('q', { s });
export const tileName = k => (lang === 'en' && TILE_EN[k]?.[0]) || TILES[k]?.name || k;
export const tileDesc = k => (lang === 'en' && TILE_EN[k]?.[1]) || TILES[k]?.desc || '';
export const biomeName = b => (lang === 'en' ? BIOME_EN[b] : BIOME_NAMES[b]) || BIOME_NAMES[b] || b;
export const groupName = g => (lang === 'en' ? GROUP_EN[g] : GROUP_NAMES[g]) || GROUP_NAMES[g] || g;
export const catName = id => (lang === 'en' ? CAT_EN[id] : CATS.find(c => c.id === id)?.name) || CATS.find(c => c.id === id)?.name || (id === 'weitere' ? t('cat.weitere') : id);
export const locale = () => (lang === 'en' ? 'en-GB' : 'de-DE');
const NF = {};
export function fmtNum(n) { const l = locale(); return (NF[l] ||= new Intl.NumberFormat(l, { maximumFractionDigits: 0 })).format(Math.round(n || 0)); }
export const fmtDate = ts => new Date(ts).toLocaleDateString(locale(), { day: 'numeric', month: 'short', year: 'numeric' });
// für Tests: alle Schlüssel/englischen Kachel-Texte vorhanden?
export const _dict = { S, TILE_EN, PHRASE_EN };
